"use client";
import { useRef } from "react";
import { typeInteractive, useTypeMotion, type TypographyMotionProps } from "./typography-shared";
import { typeStaggerProgress } from "./typography-math";
export interface TextFillWaveProps extends TypographyMotionProps {
  color?: string;
  dimColor?: string;
  accentColor?: string;
  angle?: number;
  waveWidth?: number;
  waveGap?: number;
  stagger?: number;
}
export function TextFillWave({
  text = "Every quiet mile\nshows up loud.",
  color = "#161616",
  dimColor = "#d7d5ce",
  accentColor = "#ff542c",
  angle = 95,
  waveWidth = 10,
  waveGap = 5,
  stagger = 0.3,
  ...props
}: TextFillWaveProps) {
  const root = useRef<HTMLDivElement>(null);
  useTypeMotion(
    root,
    props,
    (p, reduced) => {
      const lines = Array.from(root.current!.querySelectorAll<HTMLElement>("[data-type-fill]"));
      lines.forEach((line, i) => {
        const q = typeStaggerProgress(p, i, lines.length, stagger),
          edge = -waveWidth - waveGap + q * (100 + waveWidth * 2 + waveGap * 2);
        line.style.backgroundImage = reduced
          ? "none"
          : `linear-gradient(${angle}deg, ${color} ${edge - waveWidth - waveGap}%, ${accentColor} ${edge - waveGap}%, ${dimColor} ${edge + waveWidth}%)`;
        line.style.color = reduced ? color : "transparent";
      });
    },
    `${text}:${color}:${dimColor}:${accentColor}:${angle}:${waveWidth}:${waveGap}:${stagger}`,
  );
  return (
    <div
      ref={root}
      className={props.className}
      style={props.style}
      data-typography="text-fill-wave"
      {...typeInteractive(props.trigger)}
    >
      {text.split("\n").map((line, i) => (
        <div
          key={i}
          data-type-fill=""
          style={{
            backgroundClip: "text",
            WebkitBackgroundClip: "text",
            color,
            width: "fit-content",
            maxWidth: "100%",
          }}
        >
          {line || "\u00a0"}
        </div>
      ))}
    </div>
  );
}
